using namespace std;

vector<vector<int>> distances(vector<string>& grid) {
    // Write your solution here
    return vector<vector<int>>(grid.size(), vector<int>(grid[0].size(), 0));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int r, c;
    cin >> r >> c;
    vector<string> grid(r);
    for (int i = 0; i < r; i++) cin >> grid[i];
    vector<vector<int>> res = distances(grid);
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) cout << res[i][j] << (j + 1 < c ? ' ' : '\n');
    }
    return 0;
}

